  'skeptical': clear('ギリシャ語 skeptikos「よく考える・探究する」から。すぐには信じずに考える→「懐疑的な・疑い深い」。skeptic（懐疑論者）と同じ語源。', '66bd159fce565574'),
  'skepticism': clear('skeptic「懐疑論者」＋ -ism「〜主義・〜の性質・状態」→「懐疑・疑念」。', '5835367987e24d8a'),
