  'slice': clear('古フランス語 esclice「割れたかけら」から（ゲルマン系の語）。「薄切り・一切れ・薄く切る」。', 'a15eb913209c4f96'),
  'slick': clear('中英語 slike「滑らかな・つやのある」から。「滑らかな」、話がつるつる出る→「口達者な・巧妙な」。sleek（つやのある）と同じ語源。', '9b5e5c8be12f05f1'),
  'slide': clear('古英語 slīdan「滑る」から。「滑る・滑り落ちる・滑り台」。', '960777b219fe0f34'),
