  'slip': clear('中世低地ドイツ語 slippen「滑る」から。「滑る・滑り」、滑るように→「こっそり動く」。「伝票」の slip は細長い紙切れを表す別の語（中世オランダ語 slippe「切れ端」）から。', '12d93eef58223311'),
  'slope': clear('古英語 āslūpan「滑り去る」から来たとされる。滑り落ちるように傾いた所→「坂・斜面・傾斜する」。', '27adf918a59b060d'),
  'sloppy': clear('slop「（水などを）こぼす」＋ -y「〜のような」→こぼしてびちゃびちゃの→「だらしない・ずさんな」。', '0384860d2324cfe7'),
  'slot': clear('古フランス語 esclot「くぼみ」から。細長い溝→「細長い穴・差し込む」、決まったすき間→「（時間の）枠」。', '9cfb0fa0b52c8a6a'),
  'sluggish': clear('slug「なめくじ」＋ -ish「〜のような・やや〜」→「動きが鈍い・不活発な」。', '9efd3f8c844e867b'),
