  'smear': clear('古英語 smeoru「脂」から。脂を塗る→「塗りつける・汚れ」、評判に泥を塗る→「中傷する」。', 'abf9e0ff3e31cfbd'),
  'smell': clear('中英語 smel「におい」から。それより前の由来ははっきりしない。「におい・においがする・かぐ」。', 'fb15b9ab8f5c2b49'),
  'smother': clear('中英語 smorther「息が詰まる煙」から。煙で息を詰まらせる→「窒息させる」、火を覆って消す→「抑え込む」。', '55ead57eb78c2eb3'),
  'smuggle': clear('低地ドイツ語（北ドイツの方言）smuggeln「こっそり運ぶ」から、17世紀に英語に入った語。関税を払わずに品物を国へこっそり運び込む→「密輸する」、人目を盗んで入れる→「こっそり持ち込む」。', '77ab944a87934acc'),
  'snap': clear('中世オランダ語 snappen「かみつく」から。パクッとかみつく→「かみつく」、パチンと音を立てる→「ポキッと折れる・パチンと鳴らす」。', 'c397719b597bf16e'),
