  'sneeze': clear('中英語 fnesen「くしゃみをする」から。つづりの fn が sn と読み違えられて今の形になったとされる。「くしゃみをする・くしゃみ」。', '61668cccdb56e767'),
  'snowy': clear('snow「雪」＋ -y「〜の多い・〜のような」→「雪の・雪の降る」。', '1918d49cb1d8b991'),
