  'soar': clear('古フランス語 essorer「空へ舞い上がる」（ラテン語 ex-「外へ」＋ aura「そよ風」にさかのぼる）から。風に乗って高く上がる→「舞い上がる・急上昇する」。', 'a6f026f7dc4583b7'),
