  'sobriety': clear('ラテン語 sōbrietās「酒に酔っていないこと」（sōbrius「酔っていない」から）から。「しらふ・節制・冷静」。sober（しらふの）と同じ語源。', 'e92a8c6a5d6c90ef'),
  'social': clear('ラテン語 socius「仲間」から（sociālis「仲間の」）。仲間どうしの→「社会の」、人づきあいのよい→「社交的な」。society（社会）と同じ語源。', 'f3acfb7ce02da790'),
