  'sojourn': clear('古フランス語 sojorner「しばらく滞在する」（ラテン語 diurnus「1日の」にさかのぼる）から。何日か泊まる→「逗留・滞在」。journey（旅）と同じ語源。', 'a24984f6b8889747'),
  'solace': clear('ラテン語 sōlārī「慰める」から（sōlācium「慰め」）、古フランス語を経た語。「慰め・安らぎ」。console（慰める）と同じ語源。', '3eb86738e55c5ff6'),
