  'solicit': clear('ラテン語 sollicitāre「かき乱す・せき立てる」（sollicitus「心配した」から）から。相手の心を動かして求める→「懇願する・勧誘する」。', 'fee121e0dda735a1'),
  'solicitor': clear('solicit「頼む・求める」＋ -or「〜する人」→依頼を受けて手続きを進める人→「事務弁護士」、客を求めて回る人→「勧誘員」。', '495bf82a99d5a9b4'),
  'solicitous': clear('ラテン語 sollicitus「心をかき乱された・心配した」から。相手のことで心が落ち着かない→「気遣う・心配する」。', 'ee589c12720bb625'),
  'solicitude': clear('ラテン語 sollicitūdō「心配」（sollicitus「心配した」から）から。相手を心配する気持ち→「気遣い・配慮」。solicitous（気遣う）と同じ語源。', '69354d42038a1c1d'),
