  'sort': clear('古フランス語 sorte「種類」（ラテン語 sors「くじ・割り当て」から）から。くじで割り当てられた分け前→同じ組に分けられたもの→「種類」。', '5235029d94685ace'),
  'sound': clear('ラテン語 sonus「音」から、古フランス語 son を経た語（最後の d は後で加わった）。「音・物音」。', '7cbb86a7a74d7b06'),
  'sour': clear('古英語 sūr「酸っぱい」から。「酸っぱい」、味が悪くなるように気分が悪い→「不機嫌な」。', 'e613fb3721d23a7c'),
  'south': clear('古英語 sūþ「南」から（「太陽」を表す語と関係するとされる）。「南・南の」。', 'febc821fdd02238d'),
  'sow': clear('古英語 sāwan「（種を）まく」から。「（種を）まく」、心にまく→「植えつける」。seed（種）と同じ語源。', '50e5d0f8f25d8af8'),
  'space': clear('ラテン語 spatium「広がり・間隔」から、古フランス語 espace を経た語。「空間・余地」、地球の外に広がる空間→「宇宙」。', 'b955ca39aa2d5eb4'),
