  'span': clear('古英語 spann「手を広げたときの親指から小指までの幅」から。「幅」、ある長さにわたる→「及ぶ」、時間の幅→「期間」。', 'e5018b10b27014ad'),
  'spare': clear('古英語 sparian「節約する・大事にとっておく」から。とっておいた→「予備の・余分な」、とっておいたものを分ける→「割く」。', 'fed20f6ca4f00f17'),
  'sparingly': clear('sparing「控えめな」＋ -ly「〜に・〜く（様子を表す）」→「控えめに・倹約して」。', '079ac79896f47b43'),
  'spark': clear('古英語 spearca「火花」から。「火花・火花を散らす」、火花が火を起こすように→「引き起こす」。', 'dfe50ac56caa564a'),
  'spear': clear('古英語 spere「槍」から。「槍・突き刺す」。', '53961484a5132604'),
  'special': clear('ラテン語 speciēs「見かけ・種類」から（speciālis「特定の種類の」）。ある種類に限った→「特別な」。species（種）と同じ語源。', '0d99f3819685f948'),
