  'sphere': clear('ギリシャ語 sphaira「球」から、ラテン語を経た語。「球」、球の中のような範囲→「領域・分野」。', '3b5d0d97a7688b86'),
  'spider': clear('古英語 spīþra「クモ」（spinnan「糸を紡ぐ」から）から。糸を紡ぐ生き物→「クモ」。spin（紡ぐ）と同じ語源。', 'cc9347d8c4e6bee5'),
