  'spiral': clear('ギリシャ語 speira「巻いたもの」から、中世ラテン語 spīrālis を経た語。「らせん・らせん状の・らせんを描く」。', 'da11ea1efdd5a902'),
  'spire': clear('古英語 spīr「細長い茎・芽」から。細長くとがったもの→「尖塔・先端」。', 'bd784b9ab1a85f76'),
  'spirit': clear('ラテン語 spīritus「息・魂」（spīrāre「息をする」から）から。命の息→「霊・精神」、生き生きした息づかい→「元気」。', 'dda6ea9d369d7db4'),
