  'splendor': clear('ラテン語 splendor「輝き」（splendēre「輝く」から）から。「壮麗・華麗」。splendid（見事な）と同じ語源。', '134a1123ba275674'),
  'splinter': clear('中世オランダ語 splinter「破片」から。「とげ・破片」、破片のように割れる→「分裂する」。split（割る）と同じ語源。', '963ae90fe4a36abe'),
  'spoil': clear('ラテン語 spoliāre「（倒した敵の）武具をはぎ取る」から、古フランス語 espoillier を経た語。奪って荒らす→「台無しにする・傷む」、子どもの性格を台無しにする→「甘やかす」。', '86f872031f3bec1f'),
