  'sprain': clear('古フランス語 espreindre「絞る・締めつける」から来たとされる。関節を強くねじる→「ねんざする・くじく」。', '621cfaa2a58ceccb'),
  'sprawl': clear('古英語 sprēawlian「手足をばたつかせる」から。手足を広げる→「手足を広げて寝そべる」、だらしなく広がる→「無秩序に広がる」。', '76297e0e0495985b'),
