  'squalid': clear('ラテン語 squālidus「汚れた・荒れた」（squālēre「汚れている」から）から。「不潔な・むさ苦しい」。', '8fbb0f999cf1f29e'),
  'squall': clear('北欧系の語（スウェーデン語 skval「ほとばしる水」など）から来たとされる。急に激しく降る雨や吹く風→「スコール・突風」。', 'ea7e041168c83ccd'),
