  'square': clear('ラテン語 quadrāre「四角にする」（quadra「正方形」から）から、古フランス語 esquarre を経た語。「正方形・四角い」。', 'fc13b191f65c0fff'),
  'squeamish': clear('中英語 squeymous「むかつきやすい・好みがうるさい」から（それより前の由来ははっきりしない）。すぐ気分が悪くなる→「吐き気を催しやすい」、細かいことを嫌がる→「神経質な・潔癖な」。', '8852aaf630c3bb44'),
