  'stamp': clear('中英語 stampen「踏みつける・つき砕く」から。「踏みつける」、上から押しつけて印をつける→「印」、印を押した紙→「切手」。', 'e9e08b384228b99e'),
  'standard': clear('古フランス語 estandart「軍旗・旗印」から。兵が集まる目印の旗→従う目印→「基準・標準・水準」。', '79b67322a5231bd3'),
