  'uproar': clear('オランダ語 oproer「反乱・騒動」（op「上へ」＋ roeren「かき混ぜる」）から。英語では roar（ほえる）と結びつけて受け取られた→「大騒ぎ・激しい抗議」。', 'bab4ba8c28d4830a'),
